import os
import zipfile
import io
from flask import Flask, request, jsonify, send_file

app = Flask(__name__)

@app.route('/convert', methods=['POST'])
def convert():
    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400

    if not file.filename.endswith('.zip'):
        return jsonify({'error': 'File must be a .zip archive'}), 400

    try:
        zip_data = file.read()
        if not zipfile.is_zipfile(io.BytesIO(zip_data)):
            return jsonify({'error': 'Invalid zip file'}), 400

        text_contents = []
        with zipfile.ZipFile(io.BytesIO(zip_data), 'r') as zf:
            for name in zf.namelist():
                if name.endswith('.txt') or name.endswith('.py') or name.endswith('.js') or name.endswith('.ts') or name.endswith('.html') or name.endswith('.css') or name.endswith('.json') or name.endswith('.md'):
                    try:
                        content = zf.read(name).decode('utf-8')
                        text_contents.append(content)
                    except Exception:
                        continue

        combined_text = '\n\n'.join(text_contents)
        return combined_text, 200, {'Content-Type': 'text/plain'}
    except zipfile.BadZipFile:
        return jsonify({'error': 'Bad zip file'}), 400
    except Exception as e:
        return jsonify({'error': str(e)}), 400

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
